  str_n5_btn_battle_pass = "หนังสืออีเวนต์พิเศษ",
  str_n5_btn_progress = "อันดับดูนไฟร์",
  str_n5_total_obtain_merit = "คุณความดีทั้งหมด",
  str_n5_login_sign_title = "ล็อกอินทั้งหมด 8 วันในช่วงเวลากิจกรรม\n รับสิทธิ์ Lumamber และ Avatar รุ่นลิมิเต็ดอิดิชั่นฟรี!",
  str_n5_intro = "<color=#ee8d1a>วิธีรับคุณความดี</color>\n1. ในช่วงกิจกรรม เมื่อคุณเข้าร่วมโหมดกองหน้าทำลายล้าง คุณความดีสูงสุดที่ได้รับในสมรภูมิทั้ง 4 ที่เปิดให้เล่นจะนำไปคำนวณเป็นคุณความดีของคุณในวันนั้นและรวมเข้ากับคุณความดีสะสม\n2. โหมดกองหน้าทำลายล้างจะรีเซ็ตใหม่ทุกวัน ซึ่งคุณความดีของคุณในวันนั้นจะถูกรีเซ็ตตามไปด้วย\n3. คุณความดีประจำวันของคุณจะสะสมรวมเป็นคุณความดีสะสม เมื่อคุณความดีสะสมถึงจำนวนที่กำหนด จะปลดล็อกรางวัลที่สอดคล้องในอันดับดูนไฟร์\n<color=#ee8d1a>โหมดกองหน้าทำลายล้าง</color>\n1. ในโหมดกองหน้าทำลายล้าง คุณต้องสู้กับศัตรูหลายระลอกในการต่อสู้หนึ่งครั้ง เมื่อรีเซ็ตระลอกใหม่ ช่องบนกระดานก็จะรีเซ็ตด้วย ยิ่งเอาชนะศัตรูได้หลายระลอกเมื่อสิ้นสุดการต่อสู้มากเท่าไหร่ ก็ยิ่งจะได้รับคะแนนมากเท่านั้น\n2. มีสมรภูมิทั้งหมด 4 แบบซึ่งมีระดับความยากต่างกัน ยิ่งด่านที่เลือกมีความยากสูง ก็ยิ่งจะได้รับคะแนนมากจากการเอาชนะระลอกศัตรู\n3. โหมดกองหน้าทำลายล้างจะรีเซ็ตทุกวัน ในแต่ละวัน คุณความดีสูงสุดที่ได้รับในสมรภูมิทั้ง 4 ที่เปิดให้เล่นจะนำไปคำนวณเป็นคุณความดีของคุณในวันนั้นและรวมเข้ากับคุณความดีสะสม ทั้งนี้ไม่มีการจำกัดจำนวนครั้งการท้าทายแต่ละระดับความยากในแต่ละวัน",
  str_n5_progress_rank_title = "No.{1}",
  str_n5_progress_detail_1 = "แนวป้องกันดูนไฟร์ถูกอิคลิพไซท์โจมตีมาอย่างต่อเนื่อง และทุกกองทัพของสหพันธรัฐอิลลูมินาก็ได้รับมอบหมายหน้าที่ให้สนับสนุนการป้องกัน ชาโรนาได้นำทัพกองพลที่ 1 ขับไล่การบุกรุกของอิคลิพไซท์ไว้ได้หลายครั้ง สร้างผลงานที่ตราตรึงในการสร้างเสถียรภาพให้แก่แนวป้องกันดูนไฟร์",
  str_n5_progress_detail_2 = "กองพลที่ 3 ที่รับหน้าที่สนับสนุนและโจมตีด่วน อาจพูดได้ว่าเป็นเพื่อนเก่าของแนวป้องกันดูนไฟร์เลยก็ว่าได้ โดยผู้บัญชาการคนปัจจุบัน ฮิอิโระ ได้กลายมาเป็นตำนานของแนวป้องกันดูนไฟร์หลังจากที่สนับสนุนแนวป้องกันไว้ได้หลายครั้ง และทำให้เมืองใต้ดินหมายเลข 24 ดำเนินการต่อไปได้ตามปกติ",
  str_n5_progress_detail_3 = "แม้ว่าเขาจะเกษียณไปนานแล้ว แต่ในฐานะอดีตสมาชิกของสโตนฟอร์ซ ครั้งหนึ่งแกรมก็เคยบากบั่นไปกับการล่าอิคลิพไซท์พร้อมพรรคพวกของเขาในสมรภูมิตามแนวป้องกันดูนไฟร์อยู่ตลอดทั้งปี อิคลิพไซท์ที่ต้องตายต่อหน้าเขามันเยอะมากกว่าที่ทหารเกณฑ์ใหม่จะเข้าใจได้เลย",
  str_n5_progress_detail_4 = "แม้ว่ากองพลของเธอจะประกอบด้วยพลทหารเพียงไม่กี่นาย แต่ศักยภาพในการทำศึกสามารถรับมือศัตรูได้ทั้งหมดเลยทีเดียว ครั้งหนึ่งเธอเคยนำทหารเพียงสิบกว่าคนไปบุกล้อมอิคลิพไซท์หลายพันตัวเหนือหุบเขา ใช้ข้อได้เปรียบทางภูมิประเทศในการกำจัดพวกมันอย่างราบคาบ และสร้างประวัติการสังหารอิคลิพไซท์ที่น่าเหลือเชื่อขึ้น",
  str_n5_progress_detail_5 = "เป็นปกติที่แนวป้องกันดูนไฟร์จะเห็นบาร์ตันนำกองพลที่ 2 มาที่นี่ทุกปี เพื่อเข้าร่วมการต่อสู้ของจริง สำหรับเขาแล้ว แนวป้องกันดูนไฟร์คือสนามฝึกที่ดีที่สุด และด้วยเหตุนี้เอง กองพลที่ 2 จึงมีชื่อเสียงมากในเรื่องจำนวนอิคลิพไซท์ที่สังหารได้เยอะที่สุดท่ามกลางหน่วยทหารทั้งหมดของอิลลูมินา",
  str_n5_progress_detail_6 = "\"กองทัพจะเคลื่อนได้ อาหารต้องมาถึงก่อน\" ในฐานะหัวหน้าของหน่วยขนส่งในสหพันธรัฐอิลลูมินา ระบบขนส่งของคารอนได้จัดหาเสบียงแก่แนวป้องกันดูนไฟร์มาแล้วอย่างต่อเนื่อง เพื่อยืนยันเรื่องประสิทธิภาพแม้ว่าจะเป็นที่ที่ยังไม่มีรางรถไฟใต้ดินอิลลูมินาเลยก็ตาม",
  str_n5_progress_detail_7 = "มิการ์ดคือตำนานลึกลับของแนวป้องกันดูนไฟร์ ทหารบางคนกล่าวว่าครั้งหนึ่งเธอเคยฆ่าอิคลิพไซท์ได้หลายหมื่นตัวเพียงผู้เดียว ขณะที่บางคนก็พูดว่าเธอได้ประดิษฐ์อุปกรณ์ที่ทำให้อิคลิพไซท์อ่อนแอได้... ไม่ว่าความจริงจะคืออะไร มิการ์ดก็ได้ขับไล่การโจมตีของอิคลิพไซท์มาแล้วนับไม่ถ้วน พร้อมกับเพื่อนนักป้องกันของเธอ และความสำเร็จทางการทหารของเธอก็ไม่มีข้อกังขาเลย",
  str_n5_progress_detail_8 = "แม้ว่าเธอจะยังค่อนข้างใหม่กับแนวป้องกันดูนไฟร์ แต่เธอก็มีฝีมือด้านการต่อสู้มาตั้งแต่เด็ก และสร้างผลงานที่ยิ่งใหญ่ไว้ในช่วงเวลาสั้น ๆ ที่นี่ มันอาจต้องใช้เวลากว่าที่เธอจะชินกับการทำงานกับเพื่อนร่วมทีมในปัจจุบันของเธออย่างเต็มที่ แต่ไม่ต้องสงสัยหรอกว่าเธอน่ะได้กลายเป็นหนึ่งในดาวรุ่งของกองทัพไปเรียบร้อยแล้ว",
  str_n5_progress_detail_9 = "ผู้ปกป้องเมือง AA-88, อิคลิพไซท์รีปเปอร์ และเทวทูตบนแนวป้องกันดูนไฟร์ ในฐานะหนึ่งในยุทโธปกรณ์หลักของแนวป้องกันดูนไฟร์ มันยากที่จะบอกว่ามันได้ถูกใช้ไปในการขับไล่อิคลิพไซท์มาแล้วกี่ครั้ง ส่วนผู้ที่ประดิษฐ์มันอย่างกรอนรู ก็แน่ล่ะว่าได้รับการยกย่องให้เป็นวีรบุรุษแห่งชาติไปแล้ว",
  str_n5_progress_detail_10 = "วินัยคือรากฐานขององค์กรทหาร ในฐานะผู้ตรวจการสูงสุด เนเมซิสจึงตรวจสอบวินัยทหารที่แนวป้องกันดูนไฟร์ทุกปี ซึ่งสร้างความหวาดวิตกเหมือนว่าศัตรูจะบุกให้แก่เหล่าทหารได้ดี ด้วยการตรวจสอบแบบนี้เองที่ทำให้กองหน้าทำลายล้างตามแนวป้องกันดูนไฟร์หมั่นระมัดระวังตัว คอยตรวจสอบเรื่องวินัยว่าต้องไม่บกพร่องจนเพลี่ยงพล้ำในยามสงครามได้",
  str_n5_progress_detail_11 = "\"ตราบใดที่เรายังไม่ขาดปลาแห้ง อะไรก็มาหยุดยั้งหัวหน้าหน่วยข่าวกรองไม่ได้\" ฟิลิชีเก่งกาจเรื่องการรวบรวมข้อมูลรายละเอียดเกี่ยวกับอิคลิพไซท์ยิ่งนัก และรางวัลที่เธอได้รับส่วนใหญ่ก็มักจะเป็นปลาแห้ง ด้วยเหตุนี้คำกล่าวนี้จึงค่อย ๆ แพร่สะพัดออกไปท่ามกลางบุคคลที่ได้รับการช่วยชีวิตไว้โดยข่าวกรองของเธอ",
  str_n5_progress_detail_12 = "แม้เมืองแกนน่อนจะอยู่ไกลโพ้น แต่วิเวียนก็รู้จักแนวป้องกันดูนไฟร์เป็นอย่างดี ในการเผชิญหน้ากับการโจมตีของอิคลิพไซท์หลายครั้ง ที่ส่งผลให้แนวป้องกันดูนไพร์ถึงจุดแตกหัก เธอยังคงสงบนิ่งและวางแผนป้องกันกับการโต้กลับได้อย่างไร้ที่ติ ซึ่งปูรากฐานคงมั่นให้แก่ชัยชนะ",
  str_n5_progress_detail_13 = "แม้ว่าพวกเขาจะมีกันอยู่แค่สองคน แต่พวกเขาก็มีความกล้าหาญเต็มเปี่ยม ครั้งหนึ่งตอนที่หน่วยของพวกเขาถูกอิคลิพไซท์ห้อมล้อมแถมหัวหน้ายังได้รับบาดเจ็บสาหัส พวกเขาก็ได้ยืนหยัดต่อสู้ ปกป้องตำแหน่งเอาไว้อย่างเหนียวแน่นจนกองกำลังเสริมไปถึง และได้ขัดขวางการรุกล้ำของอิคลิพไซท์จนสำเร็จ",
  str_n5_progress_detail_14 = "สงครามที่ไม่สิ้นสุดบนแนวป้องกันดูนไฟร์ทำให้พวกทหารที่ต้องต่อสู้ทนไม่ไหวอยู่บ่อยครั้ง แรงกดดันทางจิตใจเช่นนี้ได้นำไปสู่ความสูญเสียที่ไม่จำเป็น ฉะนั้นจึงปฏิเสธไม่ได้ว่าแชนดราได้สร้างผลงานที่โดดเด่นในเรื่องสงครามของเธอ ผ่านทางงานพัฒนาสุขภาพจิตโดยรวมของกองทัพที่เธอทำ ถ้ารอยรั่วเพียงเล็กน้อยสามารถทำให้เรือที่แข็งแกร่งจมลงได้ แชนดรานี่แหละคือคนที่จะรับผิดชอบอุดรอยรั่วนั้นเอง",
  str_n5_progress_detail_15 = "เมื่อระบบขนส่งของเมืองใต้ดินหมายเลข 24 ตามแนวป้องกันดูนไฟร์หยุดการทำงานลง ยูนิเมตจึงไม่ยอมหลับยอมนอน ทำการซ่อมอุปกรณ์ที่ควรต้องใช้เวลาหนึ่งเดือน แต่กลับซ่อมเสร็จภายใน 24 ชั่วโมง เพื่อยืนยันว่าแนวป้องกันนั้นจะทำงานได้อย่างไม่มีข้อขัดข้อง",
  str_n5_progress_detail_16 = "เมื่อไวท์ดวาร์ฟมาเยือนแนวป้องกันดูนไฟร์เป็นครั้งแรก นิสัยแปลกวิเวกของเขาได้ทำให้การรวมตัวเขาเข้าไปในทีมแบบทันทีเป็นไปได้ยาก แต่อย่างไรก็ดี หลังจากที่เขาเฝ้าประจำการอยู่คนเดียวเป็นเวลาสองสัปดาห์ ขับไล่การโจมตีจากฝูงอิคลิพไซท์อยู่ซ้ำ ๆ จนกระทั่งกองกำลังเสริมมาถึง เขาก็เริ่มได้รับการเคารพจากเพื่อนร่วมสมรภูมิอย่างต่อเนื่อง",
