  str_n5_mission_desc_1 = "ขณะอยู่บนโคลอสซัส คุณได้รับข้อความจากเมืองใต้ดินอิลลูมินาอย่างไม่คาดคิด",
  str_n5_mission_desc_2 = "คุณมาถึงเมืองใต้ดินหมายเลข 24 และได้พบกับเจ้าหน้าที่ที่นัดไว้ที่นั่น",
  str_n5_mission_desc_3 = "ในฐานะสมาชิกหน้าใหม่ที่เพิ่งเข้าร่วมทีมของเขา เจ้าหน้าที่เบรนท์จึงมีทีท่ากังวลเรื่องการทำผลงานของคุณมาก",
  str_n5_mission_desc_4 = "คุณได้เข้าร่วมขบวนขนส่งแบบไม่มีอะไรสะดุด แต่ก่อนที่คุณจะเริ่มภารกิจ เบรนท์ได้แจ้งคุณว่ามิตรภาพคือสิ่งสำคัญในการพัฒนาความร่วมมือกันภายในทีม",
  str_n5_mission_desc_5 = "พายุฝุ่นกับอิคลิพไซท์ทำให้ขบวนขนส่งดำเนินการขนส่งต่อไปอีกไม่ได้ แต่แอนเซียกลับไม่ยอมล้มเลิกง่าย ๆ",
  str_n5_mission_desc_6 = "กองทัพอิคลิพไซท์กำลังรุกคืบมา แต่ไม่มีกองกำลังไหนสามารถปกป้องเมืองใต้ดินหมายเลข 24 ไว้ได้แล้ว...",
  str_n5_mission_desc_7 = "เมื่ออิคลิพไซท์บินได้ร่างยักษ์บุกโจมตี การยิงมันให้ร่วงลงคือวิธีการที่ดีที่สุด!",
  str_n5_mission_desc_8 = "หากต้องเผชิญหน้ากับอิคลิพไซท์ที่ทรงพลังสุด ๆ ก็มักจะมีผู้คนที่พร้อมยืนหยัดต่อสู้อย่างองอาจเสมอ",
  str_n5_mission_desc_9 = "ในสนามรบที่แสนโหดร้าย มีเพียงเส้นบาง ๆ ระหว่างชัยชนะกับความพ่ายแพ้เท่านั้น",
  str_n5_mission_desc_10 = "หลังสืบทอดเจตจำนงแห่งการต้านทานแล้ว บัดนี้คุณต้องเผชิญหน้ากับศัตรูที่น่าหวาดกลัวที่สุดของคุณอีกครั้ง...",
  str_n5_mission_desc_11 = "การโต้กลับยังไม่จบ ตอนนี้คุณต้องนำข่าวชัยชนะของคุณไปบอกสหายในสมรภูมิของคุณด้วย!",
  str_n5_mission_desc_12 = "การป้องกันเมืองใต้ดินหมายเลข 24 เป็นแค่ส่วนหนึ่งของการต่อสู้ในครั้งนี้เท่านั้น ตอนนี้คุณต้องเบนเข็มไปสู่เป้าหมายอื่น",
  str_n5_mission_desc_13 = "เมืองใต้ดินหมายเลข 23 ที่มีตำแหน่งอยู่ในแนวป้องกันเจอการโจมตีต่อเนื่องจากกองทัพอิคลิพไซท์ การมาของคุณจะเปลี่ยนแปลงสถานการณ์ได้หรือไม่",
  str_n5_mission_desc_14 = "หลังจากที่บาร์ตันปรากฏตัวพร้อมกองทัพของเขา คุณก็ยึดข้างหลังไว้ได้อีกครั้ง แต่ทุกสิ่งจะราบลื่นเหมือนอย่างที่เห็นจริง ๆ ไหม",
  str_n5_mission_desc_15 = "ได้เวลาประจันหน้ากับศัตรูสุดแกร่งอีกครั้งแล้ว พวกคุณต่างก็ไม่มีใครยอมถอยหนี การต่อสู้ครั้งนี้จะไม่ได้เป็นเพียงก้าวแห่งชัยชนะขั้นสุดท้าย แต่มันคือเกียรติยศแด่วีรบุรุษผู้ล่วงลับที่ได้มาที่นี่ก่อนหน้าคุณ!",
  str_n5_mission_desc_16 = "การกลับไปยังเมืองใต้ดินหมายเลข 24 จะให้ทุกคนได้ตัดสินใจว่าจะสู้เพื่ออนาคตแบบไหนกันแน่",
  str_n5_mission_desc_long_1 = "คุณเจอปัญหาด้านเทคนิคในการพยายามติดต่อกับอิลลูมินา หลังจากปรับแต่งอุปกรณ์สื่อสารแล้ว คุณก็ได้รับข้อความที่คาดไม่ถึงเรื่องการขอกำลังสนับสนุนจากเมืองใต้ดินหมายเลข 24 และเมื่อได้ฟังเหตุผลจากไวซ์แล้ว ในที่สุดคุณก็ตัดสินใจมุ่งหน้าไปยังเมืองใต้ดินหมายเลข 24",
  str_n5_mission_desc_long_2 = "คุณไปถึงสถานีขนส่งและได้พบกับเจ้าหน้าที่เบรนท์ที่นั่น หลังจากได้ฟังความตั้งใจของคุณ เจ้าหน้าที่ผู้นำกองกำลังเมืองใต้ดินหมายเลข 24 จึงได้ตัดสินใจรับตัวคุณเข้ากองของเขาไว้ทันที",
  str_n5_mission_desc_long_3 = "ด้วยความไม่แน่ใจเรื่องความฟิตของร่างกายและทักษะการออกคำสั่งของคุณ เจ้าหน้าที่เบรนท์จึงสั่งให้คุณสาธิตวิธีการต่อสู้กับอิคลิพไซท์ให้เขาดูโดยทันที ขณะที่คุณกำลังตกอยู่ในอันตรายจากการห้อมล้อมของอิคลิพไซท์นั้น นายทหารที่ชื่อแกรมก็ปรากฏตัวขึ้น",
  str_n5_mission_desc_long_4 = "แอนเซียจากขบวนขนส่งได้มาขอความช่วยเหลือจากคุณ โดยหวังว่าคุณจะช่วยไกล่เกลี่ยเรื่องความแตกต่างของขบวนขนส่งที่สมาชิกสองคนกำลังทะเลาะกันอยู่ให้ แต่หลังจากที่ได้ฟังเรื่องราวแล้ว คุณก็พบว่าต้นเหตุของเรื่องทั้งหมดมาจากตัวแอนเซียนั่นเอง",
  str_n5_mission_desc_long_5 = "แอนเซียผู้นำขบวนขนส่งได้ขอร้องอย่างจริงจังที่จะให้คุณใช้โคลอสซัสในการขนส่งสินค้าไปยังเมืองใต้ดินหมายเลข 23 ระหว่างที่คุณเตรียมตัวในช่วงสั้น ๆ อยู่นั้น คุณก็ได้ค้นพบพรสวรรค์ในการทำอาหารที่เป็นความลับของแกรม",
  str_n5_mission_desc_long_6 = "แม้ต้องปะทะกับกองทัพอิคลิพไซท์ แต่เบรนท์ก็ยังควบคุมสติในช่วงหน้าสิ่วหน้าขวานไว้ได้ดี เขาออกคำสั่งให้ใช้โคลอสซัสในการอพยพพลเรือนบางส่วน และแบ่งกองกำลังของเมืองออกเป็นสองหน่วย หนึ่งหน่วยรับหน้าที่เปิดฉากโจมตีบอสของอิคลิพไซท์ ส่วนกองกำลังที่เหลือก็ได้รับคำสั่งให้ช่วยทิ้งระเบิดใส่อิคลิพไซท์ที่มาโจมตีเมือง",
  str_n5_mission_desc_long_7 = "ทหารผ่านศึกของเมืองใต้ดินหมายเลข 24 ยิงบอสอิคลิพไซท์ร่วงสำเร็จแล้ว คุณมุ่งหน้าไปที่จุดตกของมันและเตรียมเผด็จศึกมันตามแผนปัจจุบัน แต่สนามรบมักเกิดสิ่งที่ไม่คาดคิดขึ้น จู่ ๆ แผ่นดินก็ระเบิดสนั่นหวั่นไหวขึ้นในอากาศ",
  str_n5_mission_desc_long_8 = "ขณะที่อิคลิพไซท์ร่างยักษ์โจมตีเมืองใต้ดินหมายเลข 24 เบรนท์ก็ได้กำหนดแผนการต่อสู้และตัดสินใจนำทีมขนาดเล็กไปเผชิญหน้ากับมัน และในที่สุดพวกเขาก็ใช้ภูมิประเทศและกับดักระเบิดในสถานีกำจัดอิคลิพไซท์ทรงพลังไว้ได้",
  str_n5_mission_desc_long_9 = "หลังหลบหนีระเบิดมาได้อย่างหวุดหวิด คุณก็ร้อนรนรีบกลับไปยังสถานี แต่บอสอิคลิพไซท์ที่ร่วงหล่น ซึ่งนึกว่าได้ถูกระเบิดกำจัดไปแล้ว กลับผงาดขึ้นอีกครั้งและโจมตีใส่เบรนท์...",
  str_n5_mission_desc_long_10 = "เบรนท์ถูกกองทัพอิคลิพไซท์โจมตีเข้าอย่างจัง แต่เขายังมีสปิริตต่อสู้อย่างไม่กลัวตาย และเมื่อได้เห็นคุณมาถึงอย่างรีบเร่งแล้ว เขาก็เชื่อว่าคุณจะปราบอิคลิพไซท์และปกป้องเมืองใต้ดินไว้ได้",
  str_n5_mission_desc_long_11 = "ด้วยความมุมานะอย่างไม่ย่อท้อของคุณ เมืองใต้ดินหมายเลข 24 จึงได้รับการป้องกันไว้อย่างปลอดภัยในที่สุด แกรมตัดสินใจที่จะนำข่าวชัยชนะของคุณไปบอกกับบรรดาสหายร่วมรบของเขาที่ได้จากไปแล้วพร้อมกับคำอำลา",
  str_n5_mission_desc_long_12 = "หลังจากได้ข้อสรุปว่าเป้าหมายของพวกอิคลิพไซท์คือสินค้าที่บรรทุกโดยขบวนขนส่ง คุณจึงตัดสินใจที่จะคุ้มกันเสบียงสำคัญเหล่านี้ไปให้ถึงจุดหมายปลายทางของพวกมัน ซึ่งก็คือเมืองใต้ดินหมายเลข 23 บนแนวป้องกันดูนไฟร์ หรือกองหน้าทำลายล้างที่รับมือกับการโจมตีของอิคลิพไซท์",
